<?php
require_once __DIR__.'/includes/bootstrap.php';
require_login();
$pdo=lab_database();
$q=trim((string)($_GET['q']??''));
$status=(string)($_GET['status']??'todos');
if (lab_length($q)>100) $q=substr($q,0,100);
if (!in_array($status,['todos','disponivel','emprestado','manutencao'],true)) $status='todos';
$where=[];$args=[];
if ($q!=='') { $where[]='(nome LIKE ? OR codigo LIKE ? OR categoria LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like); }
if ($status!=='todos') {$where[]='status=?';$args[]=$status;}
$sql='SELECT * FROM equipamentos'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY nome ASC LIMIT 300';
$st=$pdo->prepare($sql);$st->execute($args);$items=$st->fetchAll();
$page='equipamentos';$page_title='Equipamentos';require __DIR__.'/includes/header.php';
?>
<div class="page-heading"><div><div class="eyebrow">INVENTÁRIO</div><h1>Equipamentos</h1><p><?= is_admin()?'Cadastre, edite e acompanhe o patrimônio do laboratório.':'Confira os equipamentos disponíveis e faça uma solicitação.' ?></p></div><?php if(!is_admin()): ?><a class="button" href="<?= h(url('solicitacoes.php')) ?>">Meus pedidos →</a><?php endif; ?></div>
<?php if(is_admin()): ?><section class="panel"><div class="panel-title"><div><h2>Cadastrar equipamento</h2><p>O patrimônio precisa ser único para cada item.</p></div></div><form method="post" action="<?= h(url('actions/equipamento.php')) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="acao" value="criar"><label>Nome do equipamento *<input name="nome" maxlength="120" required placeholder="Ex.: Notebook do laboratório"></label><label>Patrimônio / código<input name="codigo" maxlength="80" placeholder="Ex.: IFRO-001"></label><label>Categoria<input name="categoria" maxlength="80" placeholder="Ex.: Computadores"></label><label>Condição<select name="status"><option value="disponivel">Disponível</option><option value="manutencao">Manutenção</option></select></label><label class="full">Descrição<textarea name="descricao" rows="2" maxlength="2000" placeholder="Informações adicionais (opcional)"></textarea></label><div class="full"><button type="submit" class="button">Adicionar equipamento</button></div></form></section><?php endif; ?>
<section class="panel"><div class="panel-title"><div><h2>Catálogo de equipamentos</h2><p><?= count($items) ?> item(ns) encontrado(s).</p></div></div><form method="get" class="filter-bar"><label class="sr-only" for="searchEquipment">Buscar equipamento</label><input id="searchEquipment" class="search-input" type="search" name="q" value="<?= h($q) ?>" placeholder="Pesquisar nome, patrimônio ou categoria" maxlength="100"><label class="sr-only" for="equipmentStatus">Filtrar por status</label><select id="equipmentStatus" name="status"><option value="todos">Todos os estados</option><?php foreach(['disponivel','emprestado','manutencao'] as $s): ?><option value="<?= h($s) ?>" <?= $status===$s?'selected':'' ?>><?= h(status_label($s)) ?></option><?php endforeach; ?></select><button class="button secondary" type="submit">Filtrar</button><a class="text-link" href="<?= h(url('equipamentos.php')) ?>">Limpar</a></form>
<div class="table-wrap"><table><thead><tr><th>Equipamento</th><th>Patrimônio</th><th>Categoria</th><th>Situação</th><th>Ação</th></tr></thead><tbody>
<?php foreach($items as $item): ?><tr><td><strong><?= h($item['nome']) ?></strong><small class="table-subtitle"><?= h($item['descricao']?:'Sem descrição') ?></small></td><td><?= h($item['codigo']?:'—') ?></td><td><?= h($item['categoria']) ?></td><td><span class="pill <?= h(status_css($item['status'])) ?>"><?= h(status_label($item['status'])) ?></span></td><td><?php if(is_admin()): ?><a class="text-link" href="<?= h(url('equipamentos.php?editar='.(int)$item['id'])) ?>">Editar</a><?php elseif($item['status']==='disponivel'): ?><a class="button small-button" href="<?= h(url('solicitacoes.php?equipamento_id='.(int)$item['id'])) ?>">Solicitar</a><?php else: ?><span class="muted">Indisponível</span><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$items): ?><tr><td colspan="5" class="empty">Nenhum equipamento encontrado.</td></tr><?php endif; ?>
</tbody></table></div></section>
<?php if(is_admin() && isset($_GET['editar'])):
$editId=(int)$_GET['editar'];$st=$pdo->prepare('SELECT * FROM equipamentos WHERE id=?');$st->execute([$editId]);$edit=$st->fetch();
if($edit): ?>
<section class="panel" id="editar"><div class="panel-title"><div><h2>Editar: <?= h($edit['nome']) ?></h2><p>Não é possível modificar equipamentos emprestados até a devolução.</p></div></div><form method="post" class="form-grid" action="<?= h(url('actions/equipamento.php')) ?>"><?= csrf_field() ?><input type="hidden" name="acao" value="editar"><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><label>Nome<input name="nome" value="<?= h($edit['nome']) ?>" maxlength="120" required></label><label>Patrimônio<input name="codigo" value="<?= h($edit['codigo']??'') ?>" maxlength="80"></label><label>Categoria<input name="categoria" value="<?= h($edit['categoria']) ?>" maxlength="80"></label><label>Condição<select name="status"><option value="disponivel" <?= $edit['status']==='disponivel'?'selected':'' ?>>Disponível</option><option value="manutencao" <?= $edit['status']==='manutencao'?'selected':'' ?>>Manutenção</option></select></label><label class="full">Descrição<textarea name="descricao" maxlength="2000" rows="2"><?= h($edit['descricao']??'') ?></textarea></label><div class="full actions"><button class="button" type="submit" <?= $edit['status']==='emprestado'?'disabled':'' ?>>Salvar alterações</button><a class="button secondary" href="<?= h(url('equipamentos.php')) ?>">Cancelar</a></div></form>
<form method="post" action="<?= h(url('actions/equipamento.php')) ?>" data-confirm="Apagar equipamento sem histórico de empréstimo?"><?= csrf_field() ?><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><button type="submit" class="text-link danger">Excluir equipamento sem histórico</button></form></section>
<?php endif; endif; ?>
<?php require __DIR__.'/includes/footer.php'; ?>
